def envelope(name, schema, paginated=False):
    S[name] = obj({'success':{'type':'boolean','enum':[True]},'message':string(500),'data':schema,**({'meta':ref('PaginationMeta')} if paginated else {})}, ['success','message','data']+(['meta'] if paginated else []))
    return ref(name)

errors = {}
for code, desc in {'400':'Malformed JSON or multipart request.','401':'Missing, invalid, expired, revoked or wrong-portal credentials.','403':'CSRF failure, insufficient role/ownership, terms gate, or recent reauthentication required.','404':'Resource absent or concealed from this caller.','409':'Duplicate combination, stale revision or invalid lifecycle transition.','413':'Payload exceeds permitted size.','415':'Unsupported or mismatched file media type.','422':'Schema or relationship validation failed.','429':'Rate or credential-attempt limit reached; retry only after Retry-After.','500':'Unexpected failure; internal details withheld.','503':'Required persistence, revocation, email, scanner or storage dependency unavailable; fail closed.'}.items():
    errors['E'+code] = {'description':desc,'content':{'application/json':{'schema':ref('ErrorResponse'),'example':{'success':False,'message':desc,'traceId':'review-example-trace'}}}}
    if code=='429': errors['E'+code]['headers']={'Retry-After':{'description':'Seconds before retry is allowed.','schema':integer(1)}}

P = {}
def query(n,s,desc='',required=False): return {'name':n,'in':'query','required':required,'description':desc or n,'schema':s}
def route(path, method, op, tag, summary, role='public', body=None, data=None, code=200, desc='', params=None, paginated=False, decision=None, multipart=False, example=None, cookies=False):
    parameters = list(params or [])
    import re
    for n in re.findall(r'\{(\w+)\}',path):
        parameters.append({'name':n,'in':'path','required':True,'schema':string(100,pattern='^[a-z][a-zA-Z0-9.]*$') if n=='key' else uuid})
    if paginated:
        parameters.extend([query('page',dict(integer(1),default=1),'One-based page.'),query('limit',dict(integer(1,100),default=20),'Maximum 100. Stable createdAt DESC, id DESC order; catalogue lists use name ASC, id ASC. No total for hidden records.')])
    if method not in ['get','head']:
        parameters.append({'$ref':'#/components/parameters/CsrfHeader'})
    auth = 'Public; no authenticated identity required.' if role=='public' else ('Refresh cookie owns the session; access cookie may have expired.' if role=='refresh' else 'Current active, email-verified '+role+' identity; server checks role, permission and resource ownership on every request.')
    text = auth+' '+desc
    if decision: text += ' DECISION REQUIRED: '+decision
    response_schema = envelope(op+'Response',data if data is not None else {'type':'object','nullable':True,'enum':[None]},paginated)
    response={'description':summary+'.','content':{'application/json':{'schema':response_schema}}}
    if example is not None: response['content']['application/json']['example']={'success':True,'message':'Success','data':example}
    if cookies:
        response['headers']={'Set-Cookie':{'description':'Two separate Set-Cookie headers: accessToken (Path=/) and refreshToken (Path=/api/v1/auth), HttpOnly; SameSite=Strict; Secure on HTTPS. Expiries match server session policy. Tokens never appear in JSON. OpenAPI header field cannot model multiple Set-Cookie lines.','schema':{'type':'string'}}}
        if op in ['logoutSession','changeOwnPassword','resetPassword']:
            response['headers']['Set-Cookie']['description']='Clear accessToken at Path=/ and refreshToken at Path=/api/v1/auth using separate Set-Cookie headers with expired dates/Max-Age=0 and original security attributes. No replacement authentication tokens.'
    codes=['400','422','429','500','503']
    if role!='public': codes+=['401']
    if role not in ['public','refresh'] or method!='get': codes+=['403']
    if '{' in path: codes+=['404']
    if method in ['post','put','patch']: codes+=['409']
    if body: codes+=['413']
    if multipart: codes+=['415']
    operation={'operationId':op,'tags':[tag],'summary':summary,'description':text,'x-required-role':role,'x-review-status':'decision-required' if decision else 'ready-for-review','security':[] if role=='public' else [{'refreshCookie':[]}] if role=='refresh' else [{'cookieAuth':[]}],'responses':{str(code):response,**{c:{'$ref':'#/components/responses/E'+c} for c in sorted(set(codes))}}}
    if parameters: operation['parameters']=parameters
    if body:
        media={'schema':ref(body)}
        operation['requestBody']={'required':True,'content':{'multipart/form-data' if multipart else 'application/json':media}}
    P.setdefault(path,{})[method]=operation
    return operation

AUTH='Identity'
route('/auth/csrf-token','get','getCsrfToken',AUTH,'Issue signed double-submit CSRF token',data=obj({'csrfToken':string(100)},['csrfToken']),desc='Sets HttpOnly signed _csrf cookie (SameSite=Strict, Path=/, Secure on HTTPS). Return token in JSON; client keeps it in memory and sends x-csrf-token on every unsafe request including login, OTP, recovery, refresh and logout. Cache-Control: no-store. No CORS wildcard with credentials.')
route('/auth/registration/email-otp/requests','post','requestRegistrationEmailOtp',AUTH,'Send registration OTP to an email before the account exists',body='EmailRequest',data=ref('Challenge'),code=202,desc='Onboarding step 1 inline "Verify" field. Creates a REGISTRATION challenge with no user. Same proposed OTP limits as email verification, plus per-email and per-IP send limits. No OTP in response.',decision='What the screen shows when the email is already registered: a uniform 202 (no account enumeration, user learns at submit) or an explicit message.')
route('/auth/registration/email-otp/verify','post','verifyRegistrationEmailOtp',AUTH,'Verify registration OTP and issue an email verification token',body='OtpRequest',data=ref('RegistrationEmailVerified'),desc='Consume once atomically; invalid, expired or used OTP returns generic 422, exhausted attempts 429. Returns a short-lived single-use emailVerificationToken (proposed 30 minutes) that POST /auth/register consumes. Cache-Control: no-store. Does not create an account or set cookies.')
route('/auth/register','post','registerStudent',AUTH,'Create student account from the four onboarding steps',body='RegisterRequest',data=ref('RegisterResult'),code=201,desc='One transaction: consume emailVerificationToken; create the user with fullName, mobileNumber, timezone, verified email and the student role only; create the student profile, subjects and guardian contact; record policy acceptances with IP and user agent; link the guardian consent and copy the guardian name and relationship onto it; audit events. Under 18 is computed on the server from dateOfBirth (UTC date). When under 18: guardian, consentToken and the Child Safety Policy acceptance are required; consent fullName and dateOfBirth must equal the submitted values, or 422 and the student re-signs. Adults: guardian is optional and stored when sent; consentToken is rejected with 422. Board required only when the category requires it. Every curriculum must match the selected category, board and level. Duplicate email returns 409. Unknown fields including role, isActive or permissions are rejected.',decision='(1) Student password rule (8 characters with one number) is weaker than SOW A1.8 and the 12-character policy; confirm scope. (2) Guardian identity is not verified: a signature drawn on the student device does not close project plan risk R4; Product and Amentorz must accept the risk in writing. (3) Step 3 copy promises SMS; Phase 1 is email only. (4) After success: automatic login or redirect to the student login. (5) Final relationship list. (6) Whether adults see step 3 at all (UI says it is required for every student under 18).')
route('/auth/email-verification/requests','post','requestEmailVerification',AUTH,'Request or resend email verification',body='EmailRequest',data=ref('Challenge'),code=202,desc='Uniform response for unknown, already verified or unverified email; opaque decoy challenge for ineligible address. At most one active challenge per user and purpose. Resend invalidates old OTP and challenge, preserving aggregate throttles. Proposed limits: six digits, 10-minute expiry, 60-second resend cooldown, five failed attempts, five sends per hour per address plus IP limit. Values require review; no OTP in response.')
route('/auth/email-verification/verify','post','verifyEmail',AUTH,'Consume email verification OTP',body='OtpRequest',desc='Consume once atomically; invalid, expired or used challenge/OTP returns generic 422, exhausted attempts 429. Marks email verified; does not authenticate or set cookies. Concurrent consumption allows only one success.')
for portal in ['student','faculty','admin']:
    op=route('/auth/'+portal+'/login','post','login'+portal.title(),AUTH,'Log in to '+portal+' portal',body='LoginRequest',data=ref('LoginResult'),cookies=True,desc='Email/password plus exact portal role required; wrong-role, unknown, locked or inactive account returns generic 401 without cookie issuance. Correct credentials with unverified email return 403. Faculty may log in before approval, but only onboarding/self-service is permitted before current terms acceptance and password activation. Audit successes and failures with UTC time, action, actorId when identifiable; never include submitted password. Replaces generic /auth/login for Amentorz; generic login must not remain a bypass.')
    op['responses']['401']={'$ref':'#/components/responses/E401'}
route('/auth/refresh','post','refreshSession',AUTH,'Rotate refresh credential and access cookie',role='refresh',data=obj({'accessExpiresAt':date,'sessionExpiresAt':date},['accessExpiresAt','sessionExpiresAt']),cookies=True,desc='Cookie-only refresh; reject token supplied in body. Atomic single-use rotation. Reuse of a consumed credential revokes the entire session family including linked access tokens. Concurrent requests must be serialized by clients; no reuse grace proposal. Recheck account, portal role, session version and expiry. Absolute session deadline does not slide. Proposed access TTL 15 minutes and absolute session TTL seven days need approval.')
route('/auth/logout','post','logoutSession',AUTH,'Revoke current session and clear cookies',desc='Idempotent even with absent/expired cookies; CSRF still required. Revoke linked access and refresh session family immediately. Clear cookies with exact original paths. Persistence failure returns 503 and clears local cookies but must not claim server revocation.',cookies=True)
route('/auth/me','get','getCurrentUser',AUTH,'Read current private identity',role='student, faculty or admin (self only)',data=ref('User'),desc='No other user ID accepted. No-store. Permitted during faculty onboarding gate.')
route('/auth/reauthenticate','post','reauthenticate',AUTH,'Confirm current password for sensitive actions',role='student, faculty or admin (self only)',body='Reauthentication',data=ref('ReauthenticationResult'),desc='Bound to current server session; no transferable credential returned. Proposed five-minute freshness. Wrong password 401, failed attempts 429. Required before admin faculty creation, approval/publication/status changes, configuration updates and private verification-document retrieval. A failed check never extends freshness.')
route('/auth/password','put','changeOwnPassword',AUTH,'Change own password',role='student, faculty or admin (self only)',body='PasswordChange',desc='Verify current password, enforce new-password policy and difference from current password. Atomically update hash, clear activation flag, revoke all sessions including caller and clear cookies. Login required again. Audit password change.',cookies=True)
